<script lang="ts">
  // Shared presentation for the explicit Campus/Admin routes.
  import { app } from '$lib/state.svelte';
  import { campusStats, percent, date, feedbackLabel } from '$lib/domain';
  import Icon from '$lib/components/Icon.svelte';
  import Badge from '$lib/components/Badge.svelte';
  import Stat from '$lib/components/Stat.svelte';
  import CampusTable from '$lib/components/CampusTable.svelte';
  import CampusMaster from '$lib/components/CampusMaster.svelte';
  import Empty from '$lib/components/Empty.svelte';
  import Indicators from './Indicators.svelte';
  import Proposals from './Proposals.svelte';
  let { id = '' }: { id?: string } = $props();
  let tab = $state('Ringkasan');
  const campus = $derived(app.data!.campuses.find(c => c.id === id));
  const stats = $derived(campusStats(app.data!, id));
  const feedback = $derived(app.data!.feedback.filter(f => f.campusId === id));
</script>
{#if !id}<div class="page-heading"><div><span class="eyebrow">JEJARING KOLABORASI</span><h1>Kampus mitra</h1><p>{app.data!.campuses.length} kampus, beragam perjalanan, satu komitmen untuk dampak berkelanjutan.</p></div><Badge tone="green">{app.data!.campuses.length} kampus · Capaian simulasi</Badge></div><div class="master-toolbar"><CampusMaster/></div><section class="panel"><CampusTable/></section>{:else}<a class="back-link" href="/admin/campuses">← Kembali ke kampus mitra</a>{#if !campus}<section class="panel"><Empty title="Kampus tidak ditemukan" description="Periksa kembali alamat kampus yang Anda buka." icon="campus"/></section>{:else}<div class="page-heading"><div class="campus-detail-title"><span class="large-avatar" style:font-size={campus.initials.length > 4 ? "13px" : undefined}>{campus.initials}</span><div><span class="eyebrow">KAMPUS MITRA · {campus.region.toUpperCase()}</span><h1>{campus.name}</h1><p>Perkembangan dan dokumentasi program DEB Putih.</p></div></div><Badge tone={stats.revisions ? 'amber' : 'green'}>{stats.revisions ? 'Perlu tindak lanjut' : 'Dalam pendampingan'}</Badge></div><div class="master-toolbar"><CampusMaster {campus}/></div><div class="tabs page-tabs">{#each ['Ringkasan', 'Indikator', 'Proposal', 'Feedback'] as t}<button class:active={tab === t} onclick={() => tab = t}>{t}{#if t === 'Feedback'}<span class="count">{feedback.length}</span>{/if}</button>{/each}</div>{#if tab === 'Ringkasan'}<div class="stats-grid"><Stat label="Progres DEB" value={percent(stats.progress)} note="Rata-rata seluruh indikator" icon="target"/><Stat label="Indikator tercapai" value={`${stats.achieved} / ${stats.total}`} note="Sudah memenuhi target" icon="check"/><Stat label="Proposal" value={stats.proposal ? `Versi ${stats.proposal.version}` : 'Belum ada'} note={stats.proposal ? 'Diajukan' : 'Belum diunggah'} icon="proposal"/><Stat label="Perlu tindak lanjut" value={String(stats.revisions)} note="Indikator dengan revisi aktif" icon="alert" tone="amber"/></div><section class="panel detail-overview"><h2>Pendampingan yang terarah</h2><p>Lihat capaian indikator, telusuri proposal, dan berikan feedback sesuai perkembangan kampus.</p><div class="button-row"><button class="button" onclick={() => tab = 'Indikator'}>Tinjau indikator<Icon name="arrow" size={17}/></button><button class="button secondary" onclick={() => tab = 'Proposal'}>Lihat proposal</button></div></section>{:else if tab === 'Indikator'}<Indicators campusId={id} embedded/>{:else if tab === 'Proposal'}<Proposals campusId={id} embedded/>{:else}<section class="panel"><div class="panel-heading"><div><h2>Riwayat feedback kampus</h2><p>Feedback selalu terhubung dengan indikator yang ditinjau.</p></div></div>{#if feedback.length}<div class="feedback-list padded">{#each feedback as f}{@const indicator = app.data!.indicators.find(i => i.id === f.indicatorId)}<article class="feedback-card"><div class="row-between"><strong>{app.data!.definitions.find(d => d.id === indicator?.definitionId)?.name}</strong><Badge tone={f.state === 'closed' ? 'green' : f.state === 'responded' ? 'blue' : 'amber'}>{f.requiresRevision ? feedbackLabel[f.state] : 'Catatan'}</Badge></div><p>{f.text}</p><div class="row-between"><small>{date(f.createdAt)} · Admin PF</small><button class="text-link" onclick={() => tab = 'Indikator'}>Tinjau indikator<Icon name="arrow" size={15}/></button></div></article>{/each}</div>{:else}<Empty title="Belum ada feedback" description="Buka tab Indikator untuk memberikan catatan kepada kampus." icon="questions"/>{/if}</section>{/if}{/if}{/if}
